export function t(lang: Language) {
  return STRINGS[lang];
}

export function taskTitle(title: string, lang: Language) {
  if (lang === 'en') return title;
  return TASKS[title]?.[lang] ?? title;
}

export const LANGUAGES: { key: Language; label: string }[] = [
  { key: 'en', label: 'English' },
  { key: 'sw', label: 'Kiswahili' },
  { key: 'fr', label: 'Français' },
];

/** The languages the whole app is written in. Worker mode also offers French. */
export const APP_LANGUAGES: { key: 'en' | 'sw'; label: string }[] = [
  { key: 'en', label: 'English' },
  { key: 'sw', label: 'Kiswahili' },
];

