export type Phrase = keyof typeof SW;
type Vars = Record<string, string | number>;

function fill(text: string, vars?: Vars) {
  if (!vars) return text;
  return text.replace(/\{(\w+)(?:\|([^|}]*)\|([^}]*))?\}/g, (whole, key: string, one?: string, many?: string) => {
    if (!(key in vars)) return whole;
    if (one !== undefined) return Number(vars[key]) === 1 ? one : (many ?? '');
    return String(vars[key]);
  });
}

/** A translator for one language. French falls back to English outside worker mode. */
export function translator(lang: Language) {
  return (phrase: Phrase, vars?: Vars) => fill(lang === 'sw' ? SW[phrase] : phrase, vars);
}

export function useLang(): Language {
  return useFarm().settings.language;
}

export function useT() {
  const lang = useLang();
  return useMemo(() => translator(lang), [lang]);
}

/** Locale for dates: Kiswahili month and weekday names when the app is in Kiswahili. */
export function dateLocale(lang: Language) {
  return lang === 'sw' ? 'sw-KE' : undefined;
}

/** "Day 7" for young birds, "Week 6" once they are older. */
export function useAgeLabel() {
  const tr = useT();
  return (day: number) => (day <= 28 ? tr('Day {n}', { n: day }) : tr('Week {n}', { n: Math.round(day / 7) }));
}
